import React from 'react';
import { useApp } from '../lib/AppContext';

const team = [['MC','Martha Chirwa','Senior Environmental Officer','Lilongwe','8','5'],['JN','James Nkhoma','Environmental Officer','Blantyre','6','4'],['RM','Ruth Moyo','Field Response Officer','Mzuzu','5','3'],['PK','Peter Kachale','Environmental Officer','Zomba','4','2']];

export default function Officers() {
  const { notify } = useApp();
  return <><div className="page-heading"><div><div className="eyebrow">TEAM MANAGEMENT</div><h1>Regional officers</h1><p>Manage your response team and active assignments.</p></div><button className="primary" onClick={() => notify('Officer invite flow is ready to connect')}>＋ Invite officer</button></div><div className="queue-summary"><div><b>12</b><span>Team members</span></div><div><b>8</b><span>Available now</span></div><div><b>23</b><span>Active assignments</span></div><div><b>4.8 <small>★</small></b><span>Average rating</span></div></div><section className="panel table-panel"><div className="panel-heading officer-heading"><div><h2>Officer directory</h2><p>Current regional response team</p></div><div className="search"><span>⌕</span><input placeholder="Search officers…"/></div></div><div className="officer-grid">{team.map((person, index) => <div className="officer-card" key={person[0]}><div className="officer-card-top"><span className={`avatar officer-avatar officer-${index}`}>{person[0]}</span><span className="available"><i/> Available</span><button className="row-more" onClick={() => notify(`${person[1]} profile`)}>···</button></div><h3>{person[1]}</h3><p>{person[2]}</p><div className="officer-location">⌖ {person[3]} Regional Office</div><div className="officer-metrics"><span><b>{person[4]}</b> active cases</span><span><b>{person[5]}</b> resolved this month</span></div></div>)}</div></section></>;
}
